/**
 * The chrome palette — "Modernist Functionalism". THE canonical source: the
 * docs site (`apps/docs/src/styles/custom.css`) and the console's
 * `tokens.css` (generated by `scripts/build-tokens.mjs`) copy these hexes
 * verbatim; `palette.test.ts` proves the docs' copy has not drifted.
 *
 * Braun / Dieter Rams functionalism: one signal blue that means "live", one
 * green that means "passed", cool slate for everything else. Tonal layering
 * instead of elevation, hairlines instead of shadows.
 *
 * `light` follows Material naming (the `--color-*` anchors in the docs'
 * comments); `dark` is the cool slate ramp around `onSurface`'s hue plus the
 * cobalt signal rungs.
 */
export const palette = Object.freeze({
  light: Object.freeze({
    /** Braun Blue — the one accent; `--color-primary`. */
    primary: "#00408b",
    /** `--color-primary-container`. */
    primaryContainer: "#0057b8",
    /** `$blue-300` — hover/active rung of the accent. */
    primaryDeep: "#001a41",
    /** `--color-secondary` — muted chrome text. */
    secondary: "#565e6c",
    /** `secondaryInk` — body text, AA on white. */
    secondaryInk: "#383e47",
    /** `--color-secondary-container` — the accent's low tint. */
    secondaryContainer: "#e6ebff",
    /** `--color-tertiary` — the one green. */
    tertiary: "#16874a",
    /** `--color-tertiary-container`. */
    tertiaryContainer: "#e1f3e7",
    /** `--color-on-surface` — the strongest ink. */
    onSurface: "#1b1c1c",
    /** Ink rung between `onSurface` and `secondaryInk`. */
    inkHigh: "#2a3038",
    /** Outline rung between `secondary` and `outlineVariant`. */
    outline: "#79818e",
    /** `--color-outline-variant` — hairlines. */
    outlineVariant: "#c2c6d4",
    /** `--color-surface` — the page. */
    surface: "#fcf9f8",
    /** `--color-surface-container-low` — a recessed panel. */
    surfaceContainerLow: "#f6f3f2",
    /** `--color-surface-container` — a raised panel. */
    surfaceContainer: "#f0eded",
  }),
  dark: Object.freeze({
    /**
     * Cool slate, darkest to lightest: page, panel, raised panel, hairline,
     * muted text, secondary text, ink, strong ink.
     */
    slate: Object.freeze([
      "#12151b",
      "#1a1e26",
      "#2a303b",
      "#565e6c",
      "#8a93a3",
      "#b8bfca",
      "#dde1e8",
      "#f2f4f8",
    ]),
    /** The same Braun Blue; blue means "live" in both themes. */
    accent: "#00408b",
    /** The accent's low tint on slate. */
    accentLow: "#1a2650",
    /** The accent's high rung on slate. */
    accentHigh: "#b9c8ff",
    /** Accent text, AA on the slate page. */
    textAccent: "#8fa4ff",
  }),
});
